import { StrictMode, useCallback, useState } from "react";
import { createRoot } from "react-dom/client";
import { ComponentContext, getStudioProApi, IComponent, StudioProApi } from "@mendix/extensions-api";
import { Agent } from "../../types/agent";
import { ContentColumn, PageContainerDialog, PageContent } from "../components/PageContainers";
import DialogFooter from "../components/DialogFooter";
import AppThemeProvider from "../components/AppThemeProvider";
import TextInputLabeled from "../components/TextInputLabeled";
import { InfoBanner } from "../components/Banner";
import FormDivider from "../components/FormDivider";
import { createStudioProLogger } from "../../config/logger";

interface AppProps {
    studioPro: StudioProApi;
    agent: Agent;
    onClose?: (result: Agent | null) => void;
}
const App: React.FC<AppProps> = ({ studioPro, agent: initialAgent, onClose }) => {

    const [agent, setAgent] = useState(initialAgent);
    const [maxTokensInput, setMaxTokensInput] = useState(initialAgent.maxTokens?.toString() ?? "");
    const [temperatureInput, setTemperatureInput] = useState(initialAgent.temperature?.toString() ?? "");
    const [topPInput, setTopPInput] = useState(initialAgent.topP?.toString() ?? "");

    const validateMaxTokens = useCallback(() => {
        if (maxTokensInput !== "" && agent.maxTokens === undefined) {
            return "Please enter a valid number.";
        }
        if (agent.maxTokens !== undefined && agent.maxTokens < 1) {
            return "Max tokens must be greater than 0 (or empty).";
        }
        return undefined;
    }, [agent.maxTokens, maxTokensInput]);

    const validateTemperature = useCallback(() => {
        if (temperatureInput !== "" && agent.temperature === undefined) {
            return "Please enter a valid number.";
        }
        if (agent.temperature !== undefined && agent.temperature < 0) {
            return "Temperature must be greater or equal to 0. You can also leave it empty to use the model's default settings.";
        }
        return undefined;
    }, [agent.temperature, temperatureInput]);

    const validateTopP = useCallback(() => {
        if (topPInput !== "" && agent.topP === undefined) {
            return "Please enter a valid number.";
        }
        if (agent.topP !== undefined && agent.topP < 0) {
            return "TopP must be greater or equal to 0. You can also leave it empty to use the model's default settings.";
        }
        return undefined;
    }, [agent.topP, topPInput]);

    const handleNumberChange = useCallback((
        field: keyof Pick<Agent, 'maxTokens' | 'temperature' | 'topP'>,
        setInputState: React.Dispatch<React.SetStateAction<string>>,
        isInteger: boolean
    ) => (value: string) => {
        const regex = isInteger ? /^-?\d+$/ : /^-?\d*\.?\d*$/;
        const allowedIncomplete = isInteger ? ["-"] : ["-", "."];

        // Validate input format
        if (value !== "" && !allowedIncomplete.includes(value) && !regex.test(value)) {
            return;
        }

        setInputState(value);

        // Handle incomplete input
        if (value === "" || allowedIncomplete.includes(value)) {
            setAgent(prev => ({ ...prev, [field]: undefined }));
            return;
        }

        // Parse and set value
        const numValue = isInteger ? parseInt(value, 10) : parseFloat(value);
        setAgent(prev => ({ ...prev, [field]: isNaN(numValue) ? undefined : numValue }));
    }, []);

    const handleOk = useCallback(() => {
        if (validateMaxTokens() || validateTemperature() || validateTopP()) {
            return; // Prevent closing if there are validation errors
        }
        onClose?.(agent);
    }, [onClose, agent, validateMaxTokens, validateTemperature, validateTopP]);

    const handleCancel = useCallback(() => {
        onClose?.(null);
    }, [onClose]);

    const handleHelp = useCallback(() => {
        window.open("https://docs.mendix.com/appstore/modules/genai/genai-for-mx/commons/#request", "_blank");
    }, []);

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainerDialog>
                <PageContent>
                    <ContentColumn>
                        <FormDivider label="Tokens">
                            <TextInputLabeled
                                label="Max tokens"
                                ariaLabel="Max tokens"
                                value={maxTokensInput}
                                description="The maximum number of tokens per request."
                                onChange={handleNumberChange('maxTokens', setMaxTokensInput, true)}
                                validate={validateMaxTokens}
                            />
                        </FormDivider>
                        <FormDivider label="Randomness">
                            <InfoBanner>
                                {"It is recommended to steer either the temperature or TopP, but not both. Review the documentation of the model provider for more information about the allowed ranges."}
                            </InfoBanner>
                            <TextInputLabeled
                                label="Temperature"
                                ariaLabel="Temperature"
                                value={temperatureInput}
                                description="Temperature controls the randomness of the model response. Low values generate a more predictable output, while higher values allow creativity and diversity."
                                onChange={handleNumberChange('temperature', setTemperatureInput, false)}
                                validate={validateTemperature}
                            />
                            <TextInputLabeled
                                label="TopP"
                                ariaLabel="TopP"
                                value={topPInput}
                                description="TopP is an alternative to temperature for controlling the randomness of the model response. TopP defines a probability threshold so that only words with probabilities greater than or equal to the threshold will be included in the response."
                                onChange={handleNumberChange('topP', setTopPInput, false)}
                                validate={validateTopP}
                            />
                        </FormDivider>
                    </ContentColumn>
                </PageContent>
                <DialogFooter
                    onOk={handleOk}
                    onCancel={handleCancel}
                    showHelp={true}
                    onHelp={handleHelp}
                />
            </PageContainerDialog>
        </AppThemeProvider>
    );
};

export const component: IComponent = {
    async loaded(componentContext: ComponentContext) {

        const studioPro = getStudioProApi(componentContext);
        const logger = createStudioProLogger(studioPro);
        const params = new URLSearchParams(location.search);
        const dialogId = params.get("dialogId");
        const agentJson = params.get("agent");

        if (!dialogId || !agentJson) {
            throw new Error("Missing required URL parameters.");
        }

        try {
            const agent: Agent = JSON.parse(decodeURIComponent(agentJson));

            const rootElement = document.getElementById("root");
            if (!rootElement) throw new Error("Failed to find the root element.");

            const root = createRoot(rootElement);

            const handleClose = (result: Agent | null) => {
                // Set the result on the component context before closing
                studioPro.ui.dialogs.closeWithResult(dialogId, result);
            };

            root.render(
                <StrictMode>
                    <App
                        studioPro={studioPro}
                        agent={agent}
                        onClose={handleClose}
                    />
                </StrictMode>
            );
        } catch (error) {
            logger.error("Error parsing agent data:", error);
            throw new Error("Error parsing agent data:", error as Error);
        }
    }
};